class GSLFunction(object):
    def __init__(self, func):
        self.func = func
    def __call__(self, x):
        return self.func(x)

def integrate(func, a, b, epsabs=1e-6, epsrel=1e-6, workspace_size=1024):
  try:
    libgslcblas = CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
    gsl = CDLL('/usr/local/gsl/lib/libgsl.so')
    func_ptr = GSLFunction(func)
    workspace = (c_double * workspace_size)() 
    result, error, nfev = _integrate_function(func_ptr, a, b, epsabs, epsrel, workspace, workspace_size)
    return result, error, nfev
  except Exception as e:
    raise RuntimeError(f'Integration failed: {e}')

