def _numpy_to_gsl_matrix(np_array: np.ndarray) -> gsl.gsl_matrix_ptr:
        if not isinstance(np_array, np.ndarray):
            raise TypeError('Input must be a NumPy array.')
        rows, cols = np_array.shape
        matrix = gsl.gsl_matrix_alloc(rows, cols)
        for i in range(rows):
            for j in range(cols):
                matrix[i, j] = np_array[i, j]
        return matrix

def _gsl_matrix_to_numpy(matrix: gsl.gsl_matrix_ptr) -> np.ndarray:
        rows, cols = matrix.get_size()
        np_array = np.zeros((rows, cols))
        for i in range(rows):
            for j in range(cols):
                np_array[i, j] = matrix[i, j]
        return np_array

def gsl_multifit_covar(jacobian: gsl.gsl_matrix_ptr, epsrel: float) -> gsl.gsl_matrix_ptr:
