def compute_covariance_matrix(jacobian: np.ndarray, epsrel: float, cov_dim: int) -> np.ndarray:
    assert isinstance(jacobian, np.ndarray), 'Jacobian matrix must be a NumPy array.'
    assert isinstance(epsrel, (float, int)), 'Relative error tolerance must be a number.'
    assert cov_dim > 0, 'Covariance matrix dimensions must be positive.'
    gsl_jacobian = _numpy_to_gsl_matrix(jacobian)
