import ctypes
from gsl import * 
class GSLFunction(object):
    def __init__(self, func):
        self.func = func
    def __call__(self, x):
        return self.func(x)

def integrate(func, a, b):
    gsl_integration_qk31.argtypes = [ctypes.POINTER(GSLFunction), ctypes.c_double, ctypes.c_double]
    gsl_integration_qk31.restype = ctypes.c_double
    gsl_integration_qk31.errcheck = lambda result, _, exception: 0
    func_ptr = GSLFunction(func)
    result, error = gsl_integration_qk31(func_ptr, a, b)
    abs_values = [abs(func(x)) for x in range(int(a), int(b) + 1)]
    oscillations = [abs(func(x) - func(x - 1)) for x in range(int(a) + 1, int(b) + 1)]
    return result, error, abs_values, oscillations

