import ctypes
import numpy as np

ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

def numpy_to_gsl_matrix_complex(np_array):
    type = gsl.gsl_matrix_complex_type()
    rows, cols = np_array.shape
    matrix = gsl.gsl_matrix_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            matrix[i, j] = np_array[i, j].real + 1j * np_array[i, j].imag
    return matrix

def gsl_vector_to_numpy(gsl_vector, size):
    vector = (ctypes.c_double * size)() 
    gsl.gsl_vector_memcpy(vector, gsl_vector) 
    return np.array([vector[i] for i in range(size)])

def compute_eigenvalues(A, B):
    A_gsl = numpy_to_gsl_matrix_complex(A)
    B_gsl = numpy_to_gsl_matrix_complex(B)
    n = A.shape[0]
    eigenvalues = (ctypes.c_double * n)() 
    gsl.gsl_eigen_genherm(A_gsl, B_gsl, eigenvalues) 
    return gsl_vector_to_numpy(eigenvalues, n)

if __name__ == '__main__':
    try:
        A = np.array([[1, 2], [2, 3]], dtype=complex)
        B = np.array([[4, 5], [6, 7]], dtype=complex)
