class GSLMatrix(object):
    def __init__(self, data):
        self.data = data
    @property
    def shape(self):
        return len(self.data), len(self.data[0])
    def as_gsl_matrix(self):
        rows, cols = self.shape
        gsl_matrix = gsl.gfloat_matrix_alloc(rows, cols)
        for i in range(rows):
            for j in range(cols):
                gsl_matrix[i][j] = self.data[i][j]
        return gsl_matrix
def find_minmax_indices(matrix):
    gsl_matrix = matrix.as_gsl_matrix()
    min_row, min_col, max_row, max_col = gsl.find_minmax_indices(gsl_matrix)
    return (min_row, min_col, max_row, max_col)

def main():
    matrix = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    indices = find_minmax_indices(GSLMatrix(matrix))
    print(f"Minimum element: ({indices[0]}, {indices[1]})")
    print(f"Maximum element: ({indices[2]}, {indices[3]})")
