class gsl_combination(ctypes.Structure):
    pass

gsl_combination.next_combination = gsl.gsl_combination_next

def get_next_combination(current_combination: tuple, n: int) -> tuple or None:
    current_combination = (c for c in current_combination)
    combination = gsl_combination( *current_combination )
    result = gsl_combination.next_combination(ctypes.cast(combination, ctypes.POINTER(gsl_combination)), n)
    if result == 0:
        return None
    else:
        return tuple(i for i in result)

